pm.test("Status code is 200", () => {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

pm.test("Products are present", () => {
    pm.expect(response.products).to.exist;
});

pm.test("At least one product is present", () => {
    pm.expect(response.products.length).to.be.above(0);
});

pm.test("Every product has required fields", () => {
    response.products.forEach(product => {
        pm.expect(product.id).to.exist;
        pm.expect(product.title).to.exist;
        pm.expect(product.description).to.exist;
    });
});

